def fit(pw, tw, extra=None):
    cols=[];nm=[]
    for a in tw:
        for b in pw:
            cols.append(t**a*P**b); nm.append(f't{a}P{b}')
    if extra:
        for n,f in extra.items(): cols.append(f); nm.append(n)
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
    nmse=np.mean((X@c-dP_dt)**2)/np.var(dP_dt)
    return nmse,nm,c
